SELECT CAST(COUNT(DISTINCT CASE WHEN p.dod IS NOT NULL THEN a.hadm_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT a.hadm_id), 0) AS mortality_rate, AVG(DISTINCT CASE WHEN d.drg_severity = 'Shock' THEN COUNT(DISTINCT d.icd_code) ELSE 0 END) AS avg_sepsis_shock_comorbidities, AVG(DISTINCT CASE WHEN d.drg_severity = 'No Shock' THEN COUNT(DISTINCT d.icd_code) ELSE 0 END) AS avg_sepsis_no_shock_comorbidities, AVG(DISTINCT CASE WHEN a.los BETWEEN 1 AND 3 THEN a.los ELSE 0 END) AS avg_los_1_3, AVG(DISTINCT CASE WHEN a.los BETWEEN 4 AND 7 THEN a.los ELSE 0 END) AS avg_los_4_7, AVG(DISTINCT CASE WHEN a.los >= 8 THEN a.los ELSE 0 END) AS avg_los_8_or_more, AVG(DISTINCT CASE WHEN a.admission_type = 'Elective' THEN 1 ELSE 0 END) AS avg_elective_admissions, AVG(DISTINCT CASE WHEN a.admission_type = 'Urgent' THEN 1 ELSE 0 END) AS avg_urgent_admissions FROM admissions a JOIN patients p ON a.subject_id = p.subject_id JOIN drgcodes d ON a.hadm_id = d.hadm_id WHERE p.gender = 'M' AND p.anchor_age = 57 AND EXTRACT(YEAR FROM CURRENT_DATE) - p.anchor_year BETWEEN 52 AND 62 AND d.drg_type = 'Sepsis' GROUP BY a.hadm_id;